<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import type { Tab } from '../../shared/model'
import type { ResourceKind,ResourceProject,ResourceVersion,ResourceSource } from '../../shared/resources'
import { api,busy,data,run,toast } from '../store'
const props=defineProps<{tab:Tab;kind:ResourceKind}>()
const emit=defineEmits<{tasks:[]}>()
const source=computed({get:()=>String(props.tab.view.resourceSource||'modrinth') as ResourceSource,set:v=>props.tab.view.resourceSource=v})
const target=computed({get:()=>String(props.tab.view.resourceInstance||''),set:v=>props.tab.view.resourceInstance=v})
const query=computed({get:()=>String(props.tab.view.resourceQuery||''),set:v=>props.tab.view.resourceQuery=v})
const game=computed({get:()=>String(props.tab.view.resourceGame||''),set:v=>props.tab.view.resourceGame=v})
const loader=computed({get:()=>String(props.tab.view.resourceLoader||''),set:v=>props.tab.view.resourceLoader=v})
const instance=computed(()=>data.instances.find(i=>i.id===target.value))
const projects=ref<ResourceProject[]>([]),total=ref(0),offset=ref(0),loading=ref(false),error=ref(''),selected=ref<ResourceProject>(),versions=ref<ResourceVersion[]>([]),versionId=ref(''),plan=ref<ResourceVersion[]>([]),planLoading=ref(false)
let searchGeneration=0,versionGeneration=0,planGeneration=0
const selection=computed(()=>({source:source.value,kind:props.kind,projectId:selected.value?.id||'',versionId:versionId.value}))
async function search(page=0){const generation=++searchGeneration;loading.value=true;error.value='';versionGeneration++;planGeneration++;planLoading.value=false;plan.value=[];versionId.value='';selected.value=undefined;offset.value=page;try{const r=await api('resource.search',{source:source.value,kind:props.kind,query:query.value,game:instance.value?.minecraft||game.value,loader:instance.value?.loader.toLowerCase()||loader.value,offset:page});if(generation===searchGeneration){projects.value=r.projects;total.value=r.total}}catch(e:any){if(generation===searchGeneration){projects.value=[];error.value=e.message}}finally{if(generation===searchGeneration)loading.value=false}}
async function details(project:ResourceProject){const generation=++versionGeneration;planGeneration++;planLoading.value=false;selected.value=project;versions.value=[];versionId.value='';plan.value=[];error.value='';try{const r=await api<ResourceVersion[]>('resource.versions',{selection:{source:source.value,kind:props.kind,projectId:project.id},instanceId:target.value||undefined});if(generation===versionGeneration){versions.value=r;versionId.value=r[0]?.id||''}}catch(e:any){if(generation===versionGeneration)error.value=e.message}}
async function preview(){const generation=++planGeneration;plan.value=[];planLoading.value=false;if(!versionId.value||!target.value)return;planLoading.value=true;error.value='';try{const r=await api<ResourceVersion[]>('resource.plan',{selection:selection.value,instanceId:target.value});if(generation===planGeneration)plan.value=r}catch(e:any){if(generation===planGeneration)error.value=e.message}finally{if(generation===planGeneration)planLoading.value=false}}
watch(versionId,preview)
watch([source,target,()=>props.kind],()=>{versionGeneration++;planGeneration++;selected.value=undefined;versions.value=[];versionId.value='';plan.value=[];void search()})
async function install(){const task=await run('resource-install','resource.install',{selection:selection.value,instanceId:target.value});if(task){toast('资源与必要依赖已加入任务中心');emit('tasks')}}
onMounted(()=>search())
</script>
<template><div class="resource-browser"><div class="resource-filters"><label>来源<select v-model="source" aria-label="资源来源"><option value="modrinth">Modrinth</option><option value="curseforge">CurseForge</option></select></label><label>目标实例<select v-model="target" aria-label="资源目标实例"><option value="">仅浏览 / 请先选择实例</option><option v-for="i in data.instances" :key="i.id" :value="i.id">{{i.name}} · {{i.minecraft}} · {{i.loader}}</option></select></label></div><div v-if="!instance" class="resource-filters"><input v-model="game" aria-label="资源游戏版本" placeholder="游戏版本（可选）"/><select v-model="loader" aria-label="资源加载器"><option value="">所有加载器</option><option v-for="l in ['fabric','forge','neoforge','quilt']" :key="l">{{l}}</option></select></div><p v-else class="field-hint">已按 {{instance.minecraft}} / {{instance.loader}} 筛选。{{instance.protected?'实例已保护，解除保护后可安装。':''}}</p><form class="input-with-button resource-search" @submit.prevent="search()"><input v-model="query" aria-label="搜索资源" placeholder="搜索名称，例如 Sodium、Fabric API…"/><button class="button primary" :disabled="loading">{{loading?'搜索中…':'搜索'}}</button></form><div v-if="error" class="inline-notice" role="alert">{{error}}</div><section v-if="selected" class="resource-detail"><div class="section-title"><h3>{{selected.name}}</h3><button class="bare" @click="selected=undefined">返回列表</button></div><p>{{selected.summary}}</p><p class="field-hint">{{selected.author}} · {{source}}</p><select v-model="versionId" class="full-input" aria-label="资源版本"><option value="">{{versions.length?'请选择版本':'暂无兼容版本 / 正在读取'}}</option><option v-for="v in versions" :key="v.id" :value="v.id">{{v.name}} · {{v.filename}} · {{(v.size/1048576).toFixed(2)}} MiB</option></select><p v-if="!target" class="field-hint">选择目标实例后可解析依赖并安装。</p><div v-if="planLoading" class="field-hint">正在核对必要依赖…</div><div v-if="plan.length" class="dependency-plan"><b>将安装 {{plan.length}} 个文件（含必要依赖）</b><p v-for="v in plan" :key="v.id">{{v.filename}} · {{(v.size/1048576).toFixed(2)}} MiB</p></div><div class="button-row"><button class="button primary" :disabled="!plan.length||planLoading||!!instance?.protected||!!instance?.running||busy.has('resource-install')" @click="install">安装到此实例</button><button class="button" @click="run('resource-open','resource.open',{source,kind,projectId:selected.id})">项目页面</button></div></section><template v-else><p class="field-hint">{{total}} 个结果 · {{source}}</p><button v-for="p in projects" :key="p.source+p.id" class="resource-result" @click="details(p)"><div><b>{{p.name}}</b><p>{{p.summary}}</p><small>{{p.author}} · {{p.downloads.toLocaleString()}} 次下载</small></div><span>查看版本 ›</span></button><p v-if="!projects.length&&!loading&&!error" class="field-hint">没有匹配的资源，试试其他关键词或版本。</p><div class="button-row pagination"><button class="button" :disabled="offset===0||loading" @click="search(Math.max(0,offset-20))">上一页</button><span>{{Math.floor(offset/20)+1}}</span><button class="button" :disabled="offset+20>=total||loading" @click="search(offset+20)">下一页</button></div></template></div></template>
